const missions=[
{title:'Email visitor services about your tickets',audience:'Attraction visitor services team',subject:'Question about tickets and arrival time',brief:'You are planning to visit the Statue of Liberty on Thursday. Write to ask about the ferry departure point, arrival time and ticket arrangements.',steps:['Write a useful subject line.','Start with Dear Visitor Services Team,','Say why you are writing: I am planning to…','Ask two specific questions using Could you please…?','Thank the team and close with Kind regards,'],a2:'Subject: Question about tickets\n\nHello,\nI am planning to visit the Statue of Liberty on Thursday. Where does the ferry leave from? What time should we arrive?\nThank you for your help.\nKind regards,\nVéronique',b1:'Subject: Question about ferry tickets and arrival time\n\nDear Visitor Services Team,\nI am planning a visit to the Statue of Liberty and Ellis Island next Thursday. Could you please confirm the ferry departure point in Manhattan and how early we should arrive for the security check? I would also like to know whether our tickets include access to both islands.\nThank you in advance for your assistance.\nKind regards,\nVéronique'},
{title:'Explain a route using a real New York landmark',audience:'A travel companion',subject:'How to get from Grand Central to SUMMIT',brief:'You are meeting a friend at Grand Central Terminal and want to visit SUMMIT One Vanderbilt nearby. Explain the nearby landmark, the direction to follow and when you will meet.',steps:['Name the starting point (Grand Central).','Name the destination (SUMMIT One Vanderbilt).','Use near, next to, across from or at.','Use a real meeting time with on / at.','Explain why this is a convenient pairing.'],a2:'Let’s meet at Grand Central at 2 p.m. SUMMIT One Vanderbilt is next to the station. We can walk there together.',b1:'Hi Emma,\n\nLet’s meet inside Grand Central Terminal near the information booth at 2 p.m. on Wednesday. It’s at East 42nd Street and Park Avenue, in Midtown Manhattan. SUMMIT One Vanderbilt is right next to the terminal, so we can walk there instead of taking another subway. Let’s check our entry time before we go because observation decks sometimes require advance booking. After our visit, if we still have energy, we could walk west along 42nd Street towards Bryant Park and the New York Public Library. That way, we can see three places in the same neighbourhood without wasting time on transport. How does that sound?\n\nSee you on Wednesday!\nVéronique'},
{title:'Change an arranged museum visit',audience:'A friend travelling with you',subject:'A change to our Thursday plan',brief:'You originally arranged a museum visit on Tuesday morning, but the forecast is better for an outdoor activity. Propose moving the museum to Thursday afternoon and replacing it with the High Line.',steps:['Mention the original arrangement using present continuous or were going to.','Explain the problem or reason using because.','Suggest the alternative using could / instead.','Confirm the new date and time.','Ask for agreement politely.'],a2:'We were going to visit the museum on Tuesday morning. Could we go on Thursday afternoon instead? We can walk on the High Line on Tuesday.',b1:'We were originally planning to visit the museum on Tuesday morning, but the weather forecast looks ideal for a walk. Could we move the museum visit to Thursday afternoon instead and explore the High Line on Tuesday? That would also give us time to have lunch at Chelsea Market. What do you think?'},
{title:'Ask an attraction to solve a booking problem',audience:'Reservations team',subject:'Request to correct a booking time',brief:'Your confirmation email says 11 a.m., but the ticket now shows 1 p.m. Explain the discrepancy politely and ask whether the original time can be restored.',steps:['Use a clear subject: Booking time discrepancy.','Address the Reservations Team.','Explain the expected time and the time shown.','Say you can provide the confirmation email.','Ask politely for a correction or alternative.'],a2:'Subject: Booking time problem\n\nDear Reservations Team,\nMy booking email says 11 a.m., but my ticket says 1 p.m. Could you please check my booking?\nThank you.\nKind regards,\nVéronique',b1:'Subject: Request to correct booking time\n\nDear Reservations Team,\nI am writing about a discrepancy in our booking. Our original confirmation states 11 a.m., whereas the digital tickets now display 1 p.m. I can forward the confirmation email if necessary. Could you please check whether our original entry time can be restored, or advise us of the closest available alternative?\nThank you for your assistance.\nKind regards,\nVéronique'}
];
let state;try{state=JSON.parse(localStorage.getItem('veronique_nyc_v2'))||{}}catch{state={}};state.selected||=[];state.assignments||={};state.answers||={};state.writing||={};state.notes||='';
const save=()=>{try{localStorage.setItem('veronique_nyc_v2',JSON.stringify(state))}catch{}};
const opt=(value,label)=>`<option value="${escapeHTML(value)}">${escapeHTML(label)}</option>`;
function init(){const today=new Date(); const iso=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'); state.start||='2027-05-03'; state.length=14; $('#startDate').value=state.start;$('#category').innerHTML=opt('','All categories')+[...new Set(places.map(x=>x.category))].map(x=>opt(x,x)).join('');$('#area').innerHTML=opt('','All NYC areas')+[...new Set(places.map(x=>x.area))].map(x=>opt(x,x)).join(''); $('#situationSelect').innerHTML=situations.map((s,i)=>opt(i,s.title)).join('');$('#missionSelect').innerHTML=missions.map((m,i)=>opt(i,m.title)).join('');$('#lessonNotes').value=state.notes;
['category','area','search'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',renderPlaces)); $('#startDate').addEventListener('change',()=>{if(!$('#startDate').value)return;state.start=$('#startDate').value;state.viewMonth=state.start.slice(0,7);save();renderPlanner()});$('#prevMonth').addEventListener('click',()=>shiftMonth(-1));$('#nextMonth').addEventListener('click',()=>shiftMonth(1));$('#goTripMonth').addEventListener('click',()=>{state.viewMonth=state.start.slice(0,7);save();renderPlanner()});$('#closeDay').onclick=closeCalendarDay;$('#doneDay').onclick=closeCalendarDay;$$('[data-close-modal]').forEach(x=>x.onclick=closeCalendarDay);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalVisible)closeCalendarDay()});$('#exportPlan').addEventListener('click',exportPlan);$('#printPlan').addEventListener('click',()=>window.print());$('#changeModel').addEventListener('click',()=>$('#changeResult').textContent=`A: We were planning to visit the museum on Tuesday morning, but ${$('#reason').value}. Could we move it to Thursday afternoon instead? B: That sounds good. What shall we do on Tuesday morning? A: We could explore the High Line and then have lunch at Chelsea Market. B: Perfect. Let's check tickets and opening hours before confirming.`);$('#resetQuiz').addEventListener('click',()=>{const topic='mixed';Object.keys(state.answers).filter(k=>k.startsWith(topic+':')).forEach(k=>delete state.answers[k]);save();renderQuiz()});$('#situationSelect').addEventListener('change',renderSituation);$('#missionSelect').addEventListener('change',renderMission);$('#lessonNotes').addEventListener('input',e=>{state.notes=e.target.value;save()});$('#exportNotes').addEventListener('click',exportNotes);$('#clearData').addEventListener('click',()=>{if(confirm('Clear your saved shortlist, itinerary, practice and notes?')){localStorage.removeItem('veronique_nyc_v2');location.reload()}});$('#menuBtn').addEventListener('click',()=>$('#nav').classList.toggle('open')); $$('#nav a').forEach(a=>a.addEventListener('click',()=>$('#nav').classList.remove('open')));state.activeDay||=localISO(dateAt(0));state.trainer||={};$$('[data-trainer]').forEach(el=>{if(state.trainer[el.dataset.trainer]!==undefined)el.value=state.trainer[el.dataset.trainer];el.addEventListener('input',()=>{state.trainer[el.dataset.trainer]=el.value;save()})});$('#listenPlan').onclick=()=>speak($('#actualPlanSentences').innerText);$('#previewReport').onclick=()=>{const e=$('#reportPreview');e.hidden=false;e.textContent=reportText()};renderWritingBank();renderPlaces();renderPlanner();renderGrammar();renderQuiz();renderSituation();renderMission();updateStats()}
function renderPlaces(){const cat=$('#category').value,area=$('#area').value,q=$('#search').value.toLowerCase().trim();const match=places.filter(p=>(!cat||p.category===cat)&&(!area||p.area===area)&&(!q||[p.name,p.area,p.desc,p.near,p.district].join(' ').toLowerCase().includes(q)));$('#placeCards').innerHTML=match.length?match.map(p=>`<article class="place"><div class="placeTop"><span class="placeIcon" aria-hidden="true">${p.icon}</span><div><h3>${escapeHTML(p.name)}</h3><div class="meta">${escapeHTML(p.category)} · ${escapeHTML(p.area)}</div></div></div><p>${escapeHTML(p.desc)}</p><p><b>Why visit?</b> ${escapeHTML(p.why)}</p><div class="fact"><b>📍 Where:</b> ${escapeHTML(p.district)}<br><b>Nearby:</b> ${escapeHTML(p.near)}<br><b>🚇 Get there:</b> ${escapeHTML(p.transit)}<br><b>⏱ Allow:</b> ${escapeHTML(p.duration)}<br><b>🕘 Best time:</b> ${escapeHTML(p.best)}<br><b>🎟 Price:</b> ${escapeHTML(p.cost)}</div><div class="placeActions"><button class="btn ${state.selected.includes(p.id)?'soft':'primary'}" data-shortlist="${p.id}">Plan this place →</button><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+', New York City')}" rel="noopener" target="_blank">Find on map ↗</a><a href="${p.url}" rel="noopener" target="_blank">Official details & tickets ↗</a></div></article>`).join(''):'<p>No places found; try another category.</p>';$$('[data-shortlist]').forEach(b=>b.addEventListener('click',()=>{pendingAttraction=b.dataset.shortlist; if(!state.selected.includes(pendingAttraction))state.selected.push(pendingAttraction);save();renderPlaces();state.viewMonth=state.start.slice(0,7);renderPlanner();$('#plan').scrollIntoView({behavior:'smooth',block:'start'});$('#calendarHint').textContent='✓ Place chosen: '+places.find(p=>p.id===pendingAttraction).name+'. Now CLICK YOUR DESIRED DATE in the calendar. The place will be ready to add, but nothing is scheduled yet.';$('#calendarHint').classList.add('attention');}));$('#shortlistList').innerHTML=state.selected.length?state.selected.map(id=>{const p=places.find(x=>x.id===id);return p?`<span class="chip">${p.icon} ${escapeHTML(p.name)} <button title="Remove" data-remove="${id}">×</button></span>`:''}).join(''):'<span class="tip">Your shortlist is empty. Explore the cards above.</span>';$$('[data-remove]').forEach(b=>b.addEventListener('click',()=>{state.selected=state.selected.filter(id=>id!==b.dataset.remove);save();renderPlaces();renderPlanner();updateStats()}));$('#selectedCount').textContent=state.selected.length}
const dateAt=n=>{const [y,m,d]=state.start.split('-').map(Number);return new Date(y,m-1,d+n,12)};const localISO=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const pretty=d=>d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const slots=['Morning','Afternoon','Evening'];let pendingAttraction=null;let modalVisible=false;const monthText=d=>d.toLocaleDateString('en-US',{month:'long',year:'numeric'});
function openCalendarDay(date){state.activeDay=date;save();modalVisible=true;$('#dayModal').hidden=false;document.body.classList.add('editingDay');renderPlanner();setTimeout(()=>{const focus=$('#pick-Morning');if(focus)focus.focus()},10)}
function closeCalendarDay(){modalVisible=false;$('#dayModal').hidden=true;document.body.classList.remove('editingDay');pendingAttraction=null;$('#calendarHint').classList.remove('attention');$('#calendarHint').textContent='Click any date to add or change morning, afternoon or evening attractions. Every event stays visible in its calendar day.';renderPlanner()}
function renderPlanner(){
  state.viewMonth||=state.start.slice(0,7);
  const [year,month]=state.viewMonth.split('-').map(Number);const first=new Date(year,month-1,1,12);const lead=(first.getDay()+6)%7;const last=new Date(year,month,0).getDate();const rows=Math.ceil((lead+last)/7);
  $('#monthTitle').textContent=monthText(first);
  const tripDates=new Set(Array.from({length:14},(_,i)=>localISO(dateAt(i))));
  const headings=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(t=>`<div class="monthWeekday" role="columnheader">${t}</div>`).join('');
  let cells='';for(let n=0;n<rows*7;n++){
    const d=new Date(year,month-1,1+n-lead,12),key=localISO(d),inMonth=d.getMonth()===month-1,inTrip=tripDates.has(key);
    const schedule=state.assignments[key]||{};const eventRows=slots.map(slot=>{const ids=schedule[slot]||[];return ids.map(id=>{const p=places.find(x=>x.id===id);return p?`<div class="monthEvent ${slot.toLowerCase()}" title="${escapeHTML(slot+' · '+p.name+' · '+p.area)}"><span class="eventTime">${slot==='Morning'?'☀':slot==='Afternoon'?'◐':'☾'}</span><span class="eventName">${escapeHTML(p.name)}</span></div>`:''}).join('')}).join('');
    const count=Object.values(schedule).flat().length;
    cells+=`<button type="button" role="gridcell" class="calendarCell ${inMonth?'':'otherMonth'} ${inTrip?'tripDay':''}" data-calendar-day="${key}" aria-label="${escapeHTML(pretty(d))}; ${count} planned attraction${count===1?'':'s'}"><div class="calendarDayHead"><span class="calendarNumber">${d.getDate()}</span>${inTrip?`<span class="tripNumber">Trip day ${Array.from({length:14},(_,i)=>localISO(dateAt(i))).indexOf(key)+1}</span>`:''}<span class="cellPlus" aria-hidden="true">+</span></div><div class="monthEventList">${eventRows||'<span class="noEvent">+ Add an attraction</span>'}</div></button>`;
  }
  $('#monthCalendar').innerHTML=headings+cells;
  $$('[data-calendar-day]').forEach(b=>b.onclick=()=>openCalendarDay(b.dataset.calendarDay));
  if(modalVisible){renderDayEditor()}
  const all=Array.from({length:14},(_,i)=>({date:localISO(dateAt(i)),label:pretty(dateAt(i))}));
  $('#actualPlanSentences').innerHTML=all.map(d=>{const activities=slots.flatMap(s=>(state.assignments[d.date]?.[s]||[]).map(id=>({s,p:places.find(x=>x.id===id)}))).filter(x=>x.p);return activities.length?`<p><b>${escapeHTML(d.label)}:</b> ${activities.map(x=>`On ${escapeHTML(d.label.split(',')[0])} ${x.s.toLowerCase()}, we're visiting ${escapeHTML(x.p.name)} in ${escapeHTML(x.p.area)}.`).join(' After that, ')}</p>`:''}).join('')||'Add attractions to your calendar to build your own sentences.';updateStats();
}
function renderDayEditor(){
 const date=state.activeDay;const d=new Date(date+'T12:00:00');$('#modalDate').textContent=pretty(d);
 const all=Array.from({length:14},(_,i)=>({date:localISO(dateAt(i)),label:pretty(dateAt(i))}));
 const ordered=[...places].sort((a,b)=>Number(state.selected.includes(b.id))-Number(state.selected.includes(a.id))||a.category.localeCompare(b.category)||a.name.localeCompare(b.name));
 const options=ordered.map(p=>`<option value="${p.id}" ${pendingAttraction===p.id?'selected':''}>${p.icon} ${escapeHTML(p.name)} · ${escapeHTML(p.area)} (${escapeHTML(p.duration)})</option>`).join('');
 $('#dayEditor').innerHTML=`<p class="modalGuide">Add one or several places to each part of your day. Choose a place and press <b>+ Add</b>. It will appear on the monthly calendar immediately. You can close this panel at any time.</p><div class="slotColumns">${slots.map(slot=>{const ids=state.assignments[date]?.[slot]||[];return `<article class="slotEditor"><h4>${slot==='Morning'?'☀️':slot==='Afternoon'?'🌤️':'🌙'} ${slot}</h4><div class="visitList">${ids.length?ids.map((id,i)=>{const p=places.find(x=>x.id===id);return p?`<div class="visit"><strong>${p.icon} ${escapeHTML(p.name)}</strong><small>${escapeHTML(p.area)} · ${escapeHTML(p.duration)} · best: ${escapeHTML(p.best)}</small><div class="visitActions"><button type="button" data-move="up" data-index="${i}" data-period="${slot}" title="Move earlier">↑</button><button type="button" data-move="down" data-index="${i}" data-period="${slot}" title="Move later">↓</button><button type="button" data-delete="${i}" data-period="${slot}">Remove</button></div><div class="moveBar"><label>Move to date<select data-target-date="${slot}-${i}">${[...all,{date,label:pretty(d)}].filter((x,i,a)=>a.findIndex(z=>z.date===x.date)===i).map(x=>`<option value="${x.date}" ${x.date===date?'selected':''}>${escapeHTML(x.label)}</option>`).join('')}</select></label><label>Part of day<select data-target-slot="${slot}-${i}">${slots.map(t=>`<option ${slot===t?'selected':''}>${t}</option>`).join('')}</select></label><button type="button" data-relocate="${i}" data-period="${slot}">Move visit</button></div></div>`:''}).join(''):'<p class="emptyHint">No attraction yet.</p>'}</div><label>Choose an attraction<select id="pick-${slot}">${options}</select></label><button type="button" class="btn primary full" data-slot-add="${slot}">+ Add to ${slot.toLowerCase()}</button><label class="tiny">Notes / future restaurant<input data-note="${slot}" placeholder="Tickets, meeting point, restaurant later…" value="${escapeHTML(state.slotNotes?.[date]?.[slot]||'')}"></label></article>`}).join('')}</div>`;
 $$('[data-slot-add]').forEach(b=>b.onclick=()=>{const slot=b.dataset.slotAdd,id=$('#pick-'+slot).value;state.assignments[date]||={};state.assignments[date][slot]||=[];if(state.assignments[date][slot].includes(id)){ $('#planFeedback').textContent='Already added to this period. Select a different attraction.';return}state.assignments[date][slot].push(id);if(!state.selected.includes(id))state.selected.push(id);pendingAttraction=null;save();renderPlanner();$('#planFeedback').textContent='✓ Added to '+slot.toLowerCase()+' on '+pretty(d)+'. Visible on the month calendar.'});
 $$('[data-delete]').forEach(b=>b.onclick=()=>{state.assignments[date][b.dataset.period].splice(+b.dataset.delete,1);save();renderPlanner();$('#planFeedback').textContent='✓ Removed from this day.'});
 $$('[data-relocate]').forEach(b=>b.onclick=()=>{const src=b.dataset.period,i=+b.dataset.relocate,k=src+'-'+i;const day=$('[data-target-date="'+k+'"]').value,slot=$('[data-target-slot="'+k+'"]').value;const source=state.assignments[date]?.[src]||[];const id=source[i];if(!id||day===date&&slot===src)return;state.assignments[day]||={};state.assignments[day][slot]||=[];if(!state.assignments[day][slot].includes(id))state.assignments[day][slot].push(id);source.splice(i,1);state.activeDay=day;state.viewMonth=day.slice(0,7);save();renderPlanner();$('#planFeedback').textContent='✓ Moved to '+pretty(new Date(day+'T12:00:00'))+' · '+slot});
 $$('[data-move]').forEach(b=>b.onclick=()=>{const a=state.assignments[date]?.[b.dataset.period];const i=+b.dataset.index,j=i+(b.dataset.move==='up'?-1:1);if(j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];save();renderPlanner()}});
 $$('[data-note]').forEach(input=>input.oninput=()=>{state.slotNotes||={};state.slotNotes[date]||={};state.slotNotes[date][input.dataset.note]=input.value;save()});
}
function shiftMonth(n){const [y,m]=state.viewMonth.split('-').map(Number);const d=new Date(y,m-1+n,1,12);state.viewMonth=localISO(d).slice(0,7);save();renderPlanner()}
