function renderGrammar(){$('#grammarCards').innerHTML=grammar.map((g,i)=>`<article class="grammarCard"><div class="grammarHead"><h3>${i+1}. ${escapeHTML(g.title)}</h3><p>${escapeHTML(g.summary)}</p></div><div class="grammarBody"><div class="grammarGrid">${g.boxes.map(([a,b,c])=>`<div class="ruleBox"><h4>${escapeHTML(a)}</h4><p>${escapeHTML(b)}</p><p class="french">${escapeHTML(c)}</p></div>`).join('')}${g.id==='compare'?`<div class="ruleBox important"><h4>How do you know short vs long?</h4><p><b>1 syllable:</b> usually -er / -est (small → smaller → smallest). <b>3+ syllables:</b> usually more / most (beautiful → more beautiful). <b>2 syllables:</b> often -y → -ier (happy → happier), but many others take more (modern → more modern); some allow both (clever, simple, quiet). Learn common forms rather than counting letters.</p><p class="french">On compte les syllabes, pas les lettres. Attention aux adjectifs à deux syllabes et aux irréguliers.</p></div>`:''}${g.id==='directions'?`<div class="ruleBox important"><h4>New York's street grid · practical skill</h4><p>In much of Manhattan, numbered <b>streets</b> run east–west, while many <b>avenues</b> run north–south. Higher street numbers generally mean further north (uptown). Fifth Avenue divides many cross streets into <b>East</b> and <b>West</b>; for example, East 42nd Street and West 42nd Street. New York uses <b>neighbourhoods and boroughs</b>, not Paris-style numbered arrondissements. Lower Manhattan and Broadway do not follow a perfect grid.</p><p class="french">« Go two blocks north » = Remontez de deux rues vers le nord. « On the corner of 42nd Street and Fifth Avenue » = à l'angle de la 42e Rue et de la Cinquième Avenue.</p></div>`:''}</div><div class="inlineQuiz"><h4>✍ Guided practice ${i+1} · ${escapeHTML(g.title)}</h4><p>Read the rule, choose an answer and get immediate feedback. Use a hint or reveal the answer if needed.</p><div id="inline-${g.id}"></div><button class="btn soft" data-reset-topic="${g.id}">↺ Reset this section</button></div></div></article>`).join('');grammar.forEach(g=>renderTopicQuiz(g.id));$$('[data-reset-topic]').forEach(b=>b.onclick=()=>{const t=b.dataset.resetTopic;Object.keys(state.answers).filter(k=>k.startsWith(t+':')).forEach(k=>delete state.answers[k]);save();renderTopicQuiz(t);updateStats()})}
function renderQuiz(){renderTopicQuiz('mixed')} 
function renderTopicQuiz(topic){const target=topic==='mixed'?'#quizBox':'#inline-'+topic;const questions=topic==='mixed'?grammar.flatMap(g=>quiz[g.id].slice(0,2).map(q=>({q,g:g.id}))):quiz[topic].map(q=>({q,g:topic}));$(target).innerHTML=questions.map(({q,g},i)=>{const key=topic+':'+i,answer=state.answers[key];return `<div class="question"><span class="number">${topic==='mixed'?'MIXED · '+g.toUpperCase():'PRACTICE'} ${i+1} / ${questions.length}</span><h4>${escapeHTML(q[0])}</h4><div class="answers">${q[1].map((a,j)=>`<button data-question="${i}" data-topic="${topic}" data-answer="${j}" class="${answer===j?(j===q[2]?'correct':'incorrect'):''}" ${answer!==undefined?'disabled':''}>${String.fromCharCode(65+j)}. ${escapeHTML(a)}</button>`).join('')}</div><div class="helpBtns"><button class="btn soft" data-hint="${i}">💡 Hint</button><button class="btn soft" data-reveal="${i}">Show answer</button></div><p class="feedback" id="feedback-${topic}-${i}" aria-live="polite">${answer!==undefined?(answer===q[2]?'✓ Correct! ':'Not quite. ')+escapeHTML(q[3]):''}</p></div>`}).join('');$$(target+' [data-question]').forEach(b=>b.onclick=()=>{const i=+b.dataset.question;state.answers[topic+':'+i]=+b.dataset.answer;save();renderTopicQuiz(topic);updateStats()});$$(target+' [data-hint]').forEach(b=>b.onclick=()=>{const q=questions[+b.dataset.hint].q;$('#feedback-'+topic+'-'+b.dataset.hint).textContent='Hint: '+q[3]});$$(target+' [data-reveal]').forEach(b=>b.onclick=()=>{const q=questions[+b.dataset.reveal].q;$('#feedback-'+topic+'-'+b.dataset.reveal).textContent='Answer: '+q[1][q[2]]+'. '+q[3]});if(topic==='mixed'){const answered=questions.filter((x,i)=>state.answers[topic+':'+i]!==undefined).length,correct=questions.filter((x,i)=>state.answers[topic+':'+i]===x.q[2]).length;$('#scoreLine').textContent=`${correct} correct / ${answered} answered (${questions.length} questions)`}}
function speak(t){if(!('speechSynthesis' in window)){alert('Speech playback is unavailable in this browser.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}
function renderSituation(){const index=+$('#situationSelect').value,s=situations[index];const natural=[['Before booking: ask about tickets','"What time should we arrive?" / "Does this ticket include both islands?" / "Are there any tickets left for Thursday?"','Do not say timed entry in ordinary conversation unless explaining the label on a booking page. A ticket might show an entry time, not the time the ferry leaves.'],['Finding your way','"Where do we catch the ferry?" / "Is this the right entrance?" / "How do we get there from the subway?"','"Where do we leave from?" is natural; "departure point" is a sign or website term.'],['Showing your ticket','"Hi, we have tickets for eleven o’clock. Here they are." / "Do you need to see our ID?"','You normally greet, show the ticket, listen and ask a short follow-up.'],['Following directions','"So we go upstairs, then turn left?" / "Sorry, could you say that again?"','Repeat the essential step in your own words instead of pretending you understood.'],['Solving a problem','"I think there might be a mistake with our booking." / "Could you check it for us?"','State the difference, show confirmation, ask what options are available.']][index];$('#situationBox').innerHTML=`<article class="scenarioCard"><h3>${escapeHTML(s.title)}</h3><p><b>Real-life context:</b> ${escapeHTML(s.setup)}</p><div class="callout"><b>What would you actually say?</b><ul class="naturalExamples">${natural[1].split(" / ").map(x=>`<li>${escapeHTML(x)}</li>`).join("")}</ul><p class="french">${escapeHTML(natural[2])}</p></div><h3>1 · Phrase bank by category</h3><label class="wide">Choose useful language<select id="situationPhrase"><option value="questions">Questions you can ask</option><option value="responses">Useful replies</option><option value="problem">Clarifying or solving problems</option></select></label><div id="realPhraseList"></div><h3>2 · Vocabulary · click to expand, translate and listen</h3><div class="vocabList">${s.words.map(w=>`<details><summary>${escapeHTML(w[0])}</summary><p><b>FR:</b> ${escapeHTML(w[1])}</p><p><b>Meaning:</b> ${escapeHTML(w[2])}</p><p><b>Example:</b> ${escapeHTML(w[3])}</p><button class="btn soft" data-speak="${escapeHTML(w[3])}">▶ Listen</button></details>`).join('')}</div><h3>3 · Listen to the staff</h3><div class="dialogue"><span class="staff">Staff member:</span> ${escapeHTML(s.staff)}<br><button class="btn soft" id="listenStaff">▶ Listen</button></div><h3>4 · Build your reply in four steps</h3><ol>${s.steps.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol><h3>5 · Your turn</h3><textarea id="scenarioAnswer" rows="5" placeholder="Write or rehearse your own response before opening a model…"></textarea><div class="helpBtns"><button class="btn soft" id="scenarioA2">See A2 model</button><button class="btn soft" id="scenarioB1">See B1/B1+ model</button><button class="btn soft" id="speakScenario">▶ Hear your response</button></div><div id="scenarioModel" class="model" hidden></div><p class="tip">Practise by speaking out loud, then compare with a model. Audio is only played when you press Listen.</p></article>`;const sets={questions:['Could you tell me where we should go?','What time should we arrive?','Is this the right line?','Does the ticket include the exhibition?'],responses:['Hi! We have two tickets for today.','Of course. Here they are.','Yes, that’s right. Thank you.','Okay, so we go upstairs and turn left.'],problem:['Sorry, I didn’t catch that.','Could you say that again more slowly?','I think there might be a mistake.','Could you check our booking, please?']};const renderPhrases=()=>{$('#realPhraseList').innerHTML=sets[$('#situationPhrase').value].map(x=>`<p class="phrase">${escapeHTML(x)} <button class="btn soft" data-play="${escapeHTML(x)}">▶</button></p>`).join('');$$('[data-play]').forEach(b=>b.onclick=()=>speak(b.dataset.play))};$('#situationPhrase').onchange=renderPhrases;renderPhrases();$('#listenStaff').onclick=()=>speak(s.staff);$$('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));$('#scenarioAnswer').value=state.scenario?.[index]||'';$('#scenarioAnswer').oninput=e=>{state.scenario||={};state.scenario[index]=e.target.value;save()};$('#scenarioA2').onclick=()=>{$('#scenarioModel').hidden=false;$('#scenarioModel').textContent='A2 model: '+s.a2};$('#scenarioB1').onclick=()=>{$('#scenarioModel').hidden=false;$('#scenarioModel').textContent='B1/B1+ model: '+s.b1};$('#speakScenario').onclick=()=>speak($('#scenarioAnswer').value.trim()||s.a2)}
const writingBank={
'Subject lines':[['Question about visiting the museum','Question concernant une visite au musée'],['Request to change our ticket time','Demande de modification de l’horaire'],['Information about accessibility','Renseignements sur l’accessibilité'],['Meeting on Thursday afternoon','Rendez-vous jeudi après-midi']],
'Greetings':[['Hello,','Bonjour, (neutre)'],['Dear Visitor Services Team,','Bonjour à l’équipe d’accueil des visiteurs,'],['Dear Reservations Team,','À l’attention de l’équipe des réservations,'],['Dear Ms Johnson,','Chère Madame Johnson (si son nom est connu)'],['Hi Emma,','Salut Emma (à une amie)']],
'Purpose':[['I am writing to ask about…','Je vous écris pour me renseigner sur…'],['We are planning to visit…','Nous prévoyons de visiter…'],['I have a question about our booking.','J’ai une question concernant notre réservation.'],['I am contacting you because…','Je vous contacte parce que…']],
'Questions':[['Could you please confirm the opening time?','Pourriez-vous confirmer l’heure d’ouverture ?'],['Could you tell us where the entrance is?','Pourriez-vous nous indiquer où se trouve l’entrée ?'],['Is there a way to change our booking?','Est-il possible de modifier notre réservation ?'],['Does our ticket include the ferry?','Notre billet inclut-il le ferry ?'],['What should we do if we arrive late?','Que devons-nous faire si nous arrivons en retard ?']],
'Explaining problems':[['Our confirmation says 11 a.m., but the ticket shows 1 p.m.','Notre confirmation indique 11 h, mais le billet affiche 13 h.'],['Unfortunately, we cannot make it at that time.','Malheureusement, nous ne pouvons pas venir à cette heure-là.'],['I have attached our confirmation email.','J’ai joint notre courriel de confirmation.']],
'Thanks & closings':[['Thank you for your help.','Merci de votre aide.'],['Thank you in advance for your assistance.','Je vous remercie par avance de votre aide.'],['I look forward to hearing from you.','Dans l’attente de votre réponse.'],['Kind regards,','Bien cordialement,'],['Best regards,','Cordialement,'],['Many thanks,','Merci beaucoup, (moins formel)'],['See you soon,','À bientôt (à un ami)']]};
function renderWritingBank(){$('#writingPhraseCategory').innerHTML=Object.keys(writingBank).map(x=>opt(x,x)).join('');const show=()=>$('#writingPhrases').innerHTML=writingBank[$('#writingPhraseCategory').value].map(([en,fr])=>`<div class="phrasePair"><b>${escapeHTML(en)}</b><span>${escapeHTML(fr)}</span><button class="btn soft" data-copy="${escapeHTML(en)}">Copy</button></div>`).join('');$('#writingPhraseCategory').onchange=show;show();$('#writingPhrases').addEventListener('click',e=>{const b=e.target.closest('[data-copy]');if(b)navigator.clipboard?.writeText(b.dataset.copy)})}
function renderMission(){const idx=+$('#missionSelect').value,m=missions[idx];$('#missionBox').innerHTML=`<article class="missionCard"><h3>${escapeHTML(m.title)}</h3><p><b>Who?</b> ${escapeHTML(m.audience)}</p><p><b>Suggested subject:</b> ${escapeHTML(m.subject)}</p><p><b>Your mission:</b> ${escapeHTML(m.brief)}</p><div class="callout"><b>Before you start · notice the register</b><p>${idx===1||idx===2?'This is a message or explanation to someone travelling with you. Be friendly and practical. You do not need a formal subject line unless you send an email. Describe what you know, what you suggest and why.':'This is a genuine information request to a team. Choose a clear subject line, a neutral greeting, your dates and details, two precise questions, then a polite closing.'}</p><p><b>Improve your answer:</b> connect ideas with because / so / after that / however / instead / if possible. Explain where, when, and why — not simply a list of places.</p></div><h3>Step-by-step writing plan · do not skip a step</h3><p>Use the phrase bank above for your greeting, purpose, specific questions and closing. Add real dates and ticket details where relevant.</p><ol>${m.steps.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ol><label class="wide">Write your own answer<textarea id="missionAnswer" placeholder="Write your subject, greeting, message and closing where appropriate."></textarea></label><div class="helpBtns"><button class="btn soft" id="showA2">See A2 model</button><button class="btn soft" id="showB1">See B1/B1+ model</button><button class="btn soft" id="hearModel">▶ Listen to the model</button></div><pre id="modelText" class="model" style="white-space:pre-wrap" hidden></pre><p class="tip" id="wordCount">0 words · try to include the purpose, relevant details and a polite closing.</p></article>`;$('#missionAnswer').value=state.writing[idx]||'';$('#missionAnswer').addEventListener('input',e=>{state.writing[idx]=e.target.value;save();$('#wordCount').textContent=e.target.value.trim().split(/\s+/).filter(Boolean).length+' words · saved locally'});$('#showA2').onclick=()=>{$('#modelText').hidden=false;$('#modelText').textContent='A2 MODEL\n'+m.a2};$('#showB1').onclick=()=>{$('#modelText').hidden=false;$('#modelText').textContent='B1/B1+ MODEL\n'+m.b1};$('#hearModel').onclick=()=>speak($('#modelText').hidden?m.a2:$('#modelText').textContent)}
function plannedCount(){return Object.values(state.assignments).flatMap(d=>Object.values(d)).flat().length}function updateStats(){$('#savedPlaces').textContent=state.selected.length;$('#savedSlots').textContent=plannedCount();$('#savedCorrect').textContent=Object.entries(state.answers).filter(([k,a])=>{const [t,i]=k.split(':');const qs=t==='mixed'?grammar.flatMap(g=>quiz[g.id].slice(0,2)):quiz[t];return qs&&qs[+i]&&qs[+i][2]===a}).length}
function download(name,content){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportPlan(){let lines=['VERONIQUE · NEW YORK ITINERARY',`Start date: ${state.start}`,`Duration: ${state.length} days`,'', 'SHORTLIST',...state.selected.map(id=>places.find(p=>p.id===id)?.name||id),'','DAILY SCHEDULE'];for(let i=0;i<state.length;i++){const d=dateAt(i),key=localISO(d);lines.push('',pretty(d));slots.forEach(slot=>{const visits=(state.assignments[key]||{})[slot]||[];lines.push(`${slot}: ${visits.length?visits.map(id=>places.find(p=>p.id===id)?.name||id).join(' + '):'Not planned'}`)})}lines.push('','Verify opening hours, tickets, locations and travel logistics on official sources before booking.');download('Veronique_NYC_itinerary.txt',lines.join('\n'))}
function exportNotes(){download('Veronique_NYC_full_pedagogical_report.txt',reportText())}
function reportText(){const trainer=Object.fromEntries($$('[data-trainer]').map(e=>[e.dataset.trainer,e.value]));const total=grammar.reduce((n,g)=>n+quiz[g.id].length,0),correct=Object.entries(state.answers).filter(([k,a])=>{const [t,i]=k.split(':');const qs=t==='mixed'?grammar.flatMap(g=>quiz[g.id].slice(0,2)):quiz[t];return qs&&qs[+i]&&qs[+i][2]===a}).length;let parts=['VÉRONIQUE · NEW YORK REAL TALK','B1.1 · Travel English + LILATE preparation','',`Date: ${trainer.date||'Not entered'}`,`Duration: ${trainer.duration||'—'} hour(s)`,`Overall: ${trainer.level||'—'}`,`Speaking: ${trainer.speaking||'—'}`,`Writing: ${trainer.writing||'—'}`,`Listening: ${trainer.listening||'—'}`,'','SESSION OBJECTIVES',trainer.objectives||'', '','ACTIVITIES COMPLETED',trainer.activities||'','', 'COMPETENCIES',trainer.competencies||'','','ASSESSMENT METHODS',trainer.methods||'','','AUTOMATIC PRACTICE'];grammar.forEach(g=>{const attempted=quiz[g.id].filter((q,i)=>state.answers[g.id+':'+i]!==undefined).length;const right=quiz[g.id].filter((q,i)=>state.answers[g.id+':'+i]===q[2]).length;parts.push(`${g.title}: ${right}/${attempted} correct (${quiz[g.id].length} questions)`)});parts.push('',`Total correct answered including review: ${correct}`,'',`Shortlist: ${state.selected.map(id=>places.find(p=>p.id===id)?.name||id).join(', ')}`,`Planned visits: ${plannedCount()}`,'','DAILY PLAN');for(let i=0;i<14;i++){const d=localISO(dateAt(i));parts.push(pretty(dateAt(i)));slots.forEach(slot=>{parts.push('  '+slot+': '+(state.assignments[d]?.[slot]||[]).map(id=>places.find(p=>p.id===id)?.name||id).join(' + '));const note=state.slotNotes?.[d]?.[slot];if(note)parts.push('    Notes: '+note)})}parts.push('','WRITTEN TASKS');missions.forEach((m,i)=>parts.push(m.title+'\n'+(state.writing[i]||'(not completed)')));parts.push('','ROLE PLAYS');situations.forEach((s,i)=>parts.push(s.title+'\n'+(state.scenario?.[i]||'(not completed)')));parts.push('','NEW WEATHER / COMMUNICATION PRACTICE');
 const ea=state.enhancedAnswers||{};['weather-conditions','weather-forecast','weather-predictions','weather-decisions','reason',...situations.map((x,i)=>'scenario-'+i)].forEach(k=>{const a=Object.keys(ea).filter(x=>x.startsWith(k+':'));parts.push(k+': '+a.length+' answers attempted')});
 parts.push('Spoken role-play checkpoints: '+Object.values(state.speakingChecks||{}).reduce((n,x)=>n+Object.values(x).filter(Boolean).length,0));
 if(state.reasonConversation)parts.push('Plan-change conversation: '+state.reasonConversation);
 parts.push('','TRAINER OBSERVATIONS',trainer.observations||'','', 'NEXT STEPS',trainer.next||'', '','ADDITIONAL TRAINER NOTES',state.notes||'');return parts.join('\n')}
document.addEventListener('DOMContentLoaded',init);
